# flutter-remote:managed sha256=eae857caac79689c — generated by flutter-remote; edits are kept, `flutter-remote init --force` restores it
# Every command the Mac runs for one flutter-remote session. Provider-neutral: the
# GitHub workflow (and later Codemagic) only sets up tools and calls this file.
#
#   bash session.sh fingerprint   print the 16-character build cache key
#   bash session.sh start         boot Simulator, stream, tunnel, build, install, launch
#   bash session.sh hold          keep the session open for FR_MINUTES minutes
#   bash session.sh end           report that the session ended (never fails)
#
# Inputs are FR_* environment variables (see docs/rebuild/PLAN.md section 4.1).
# Runs on macOS: bash 3.2 only. Run from the Flutter project root.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# Inputs and defaults.
: "${FR_MINUTES:=10}"
: "${FR_DEVICE:=iPhone 17 Pro}"
: "${FR_MODE:=build}"
: "${FR_BUILD_MODE:=debug}"
: "${FR_FLAVOR:=}"
: "${FR_TARGET:=}"
: "${FR_DART_DEFINES:=}"
: "${FR_APP_URL:=}"
: "${FR_APP_RELEASE_ASSET:=}"
: "${FR_TRANSPORT:=webrtc}"
: "${FR_CODEC:=mjpeg}"
: "${FR_TUNNEL_PROTOCOL:=quic}"
: "${FR_MAX_DIMENSION:=960}"
: "${FR_VIDEO_FPS:=24}"
: "${FR_VIDEO_QUALITY:=0.6}"
: "${FR_AGENT_DEVICE:=false}"
: "${FR_AGENT_DEVICE_VERSION:=0.20.1}"
# Only the fingerprint uses these two (the old workflow hashed them into the key).
: "${FR_RUNNER:=}"
: "${FR_FLUTTER_VERSION:=}"

GATE_PORT=3199
PREVIEW_PORT=3200
SIGNAL_PORT=3201
AGENT_PORT=4310
STATE_FILE="${RUNNER_TEMP:-/tmp}/flutter-remote-state.env"

# report <state> <description> [url]: tell whoever is watching (GitHub status, relay).
report() {
  local state="$1" desc="$2" url="${3:-}"
  echo "flutter-remote: state=$state url=$url desc=$desc"
  if [ -n "${GITHUB_ACTIONS:-}" ]; then
    local args=(-f "state=$state" -f "context=flutter-remote/${FR_SESSION:-}" -f "description=$desc")
    if [ -n "$url" ]; then args+=(-f "target_url=$url"); fi
    gh api "repos/$GITHUB_REPOSITORY/statuses/$GITHUB_SHA" "${args[@]}"
  fi
  if [ -n "${FR_RELAY_TOPIC:-}" ]; then
    local json
    json=$(node -e 'console.log(JSON.stringify({ state: process.argv[1], description: process.argv[2], url: process.argv[3] }))' "$state" "$desc" "$url")
    curl -fsS -m 10 -d "$json" "${FR_RELAY_URL:-}/$FR_RELAY_TOPIC" || true
  fi
}

phase_fingerprint() {
  SOURCE_HASH=$(find pubspec.yaml pubspec.lock lib ios -type f 2>/dev/null \
    | sort \
    | xargs shasum -a 256 2>/dev/null \
    | shasum -a 256 \
    | awk '{print $1}')
  BUILD_KEY="signed-v1-${SOURCE_HASH}-${FR_RUNNER}-${FR_FLUTTER_VERSION}-${FR_BUILD_MODE}-${FR_FLAVOR}-${FR_TARGET}-${FR_DART_DEFINES}"
  FULL_HASH=$(printf '%s' "$BUILD_KEY" | shasum -a 256 | awk '{print substr($1, 1, 16)}')
  # stdout carries only the key, so the log line goes to stderr
  echo "Flutter build cache fingerprint: $FULL_HASH" >&2
  echo "$FULL_HASH"
}

boot_simulator() {
  DEVICE="$FR_DEVICE"

  UDID=$(xcrun simctl list devices available \
    | grep -F "$DEVICE (" \
    | head -1 \
    | sed -E 's/.*\(([0-9A-Fa-f-]{36})\).*/\1/' || true)

  if [ -z "$UDID" ]; then
    echo "::warning::Requested device '$DEVICE' was not available on this runner."
    FALLBACK_NAME=$(xcrun simctl list devices available | grep -E '^\s+iPhone' | tail -1 | sed -E 's/^\s+([^()]+)\s+\(.*/\1/')
    echo "::warning::Using fallback device: $FALLBACK_NAME"
    UDID=$(xcrun simctl list devices available \
      | grep -E '^\s+iPhone' \
      | tail -1 \
      | sed -E 's/.*\(([0-9A-Fa-f-]{36})\).*/\1/')
  fi

  [ -n "$UDID" ] || { echo "::error::No iOS simulator available on this runner image"; exit 1; }

  echo "Booting iOS Simulator UDID: $UDID"
  xcrun simctl boot "$UDID" || true
  xcrun simctl bootstatus "$UDID" -b
  echo "iOS Simulator is booted and ready."
}

start_serve_sim() {
  CODEC="$FR_CODEC"
  if [ "$CODEC" = "auto" ]; then
    echo "Normalizing codec 'auto' to 'mjpeg' for stable WebRTC pipeline"
    CODEC="mjpeg"
  fi
  ARGS=(
    --detach
    --quiet
    --fit
    --panes none
    --port "$PREVIEW_PORT"
    --codec "$CODEC"
  )

  echo "Starting serve-sim with codec=$CODEC args: ${ARGS[*]}"
  SERVE_SIM_OUT=$(npx --yes serve-sim "${ARGS[@]}" "$UDID" || true)
  echo "serve-sim raw output: $SERVE_SIM_OUT"

  for i in {1..30}; do
    if nc -z 127.0.0.1 "$PREVIEW_PORT" 2>/dev/null; then break; fi
    sleep 0.2
  done
  echo "serve-sim started on port $PREVIEW_PORT"

  # Extract streamUrl if reported by serve-sim, otherwise derive from simulator UDID
  STREAM_PATH=$(node -e '
    const out = process.argv[1] || "";
    const udid = process.argv[2] || "";
    let streamUrl = "";
    try {
      const parsed = JSON.parse(out);
      streamUrl = parsed.streamUrl || parsed.url || "";
    } catch {
      const match = out.match(/"streamUrl"\s*:\s*"([^"]+)"/) || out.match(/http:\/\/[^\s]+/);
      if (match) streamUrl = match[1] || match[0];
    }
    if (streamUrl) {
      try {
        const u = new URL(streamUrl);
        let p = u.pathname;
        if (!p.includes("stream.mjpeg")) {
          p = p.replace(/\/?$/, "/stream.mjpeg");
        }
        p += (p.includes("?") ? "&" : "?") + "raw=1";
        console.log(p);
        process.exit(0);
      } catch {}
    }
    if (udid) {
      console.log(`/helper/${udid}/stream.mjpeg?raw=1`);
    } else {
      console.log("/stream.mjpeg?raw=1");
    }
  ' "$SERVE_SIM_OUT" "$UDID")

  echo "Derived stream path: $STREAM_PATH"

  # serve-sim's input socket is /helper/<udid>/ws (binary frames), not /ws.
  # Use the wsUrl serve-sim reports; when it reports none, the peer derives
  # it from the stream path.
  INPUT_PATH=$(node -e '
    const out = process.argv[1] || "";
    let ws = "";
    try { ws = JSON.parse(out).wsUrl || ""; } catch {
      const m = out.match(/"wsUrl"\s*:\s*"([^"]+)"/);
      if (m) ws = m[1];
    }
    try { if (ws) console.log(new URL(ws).pathname); } catch {}
  ' "$SERVE_SIM_OUT")
  echo "Input socket path: ${INPUT_PATH:-<derived from stream path>}"
}

install_peer_deps() {
  echo "Installing WebRTC peer dependencies (node-datachannel, ws, ffmpeg-static)..."
  npm install -g node-datachannel@0.33.4 ws@8.18.0 ffmpeg-static@5.3.0 --prefer-offline
}

start_peer() {
  NODE_PATH="$(npm root -g)" \
  FLUTTER_REMOTE_TARGET_PORT="$PREVIEW_PORT" \
  FLUTTER_REMOTE_WEBRTC_SIGNAL_PORT="$SIGNAL_PORT" \
  FLUTTER_REMOTE_TRANSPORT="$FR_TRANSPORT" \
  FLUTTER_REMOTE_STREAM_PATH="${STREAM_PATH:-/helper/$UDID/stream.mjpeg?raw=1}" \
  FLUTTER_REMOTE_INPUT_PATH="$INPUT_PATH" \
  FLUTTER_REMOTE_MAX_DIMENSION="$FR_MAX_DIMENSION" \
    nohup node "$HERE/webrtc-peer.cjs" > webrtc-peer.log 2>&1 &
  disown
  for i in $(seq 1 30); do
    if nc -z 127.0.0.1 "$SIGNAL_PORT" 2>/dev/null; then break; fi
    sleep 0.2
  done
  echo "WebRTC peer bridge running on port $SIGNAL_PORT"
  echo "--- WebRTC peer startup log ---"
  cat webrtc-peer.log || true
  echo "--- End WebRTC peer startup log ---"
}

start_gate() {
  local agent_port=""
  if [ "$FR_AGENT_DEVICE" = "true" ]; then agent_port="$AGENT_PORT"; fi
  # The relay scales frames with the ffmpeg-static installed for the peer (NODE_PATH).
  # serve-sim's viewer gets scaled, de-duplicated, rate-capped frames (stream-relay.cjs).
  NODE_PATH="$(npm root -g)" \
  FLUTTER_REMOTE_GATE_TOKEN="$FR_GATE_TOKEN" \
  FLUTTER_REMOTE_GATE_PORT="$GATE_PORT" \
  FLUTTER_REMOTE_TARGET_PORT="$PREVIEW_PORT" \
  FLUTTER_REMOTE_AGENT_PORT="$agent_port" \
  FLUTTER_REMOTE_TURN_KEY_ID="${FLUTTER_REMOTE_TURN_KEY_ID:-}" \
  FLUTTER_REMOTE_TURN_KEY_TOKEN="${FLUTTER_REMOTE_TURN_KEY_TOKEN:-}" \
  FLUTTER_REMOTE_WEBRTC_SIGNAL_PORT="$SIGNAL_PORT" \
  FLUTTER_REMOTE_TRANSPORT="$FR_TRANSPORT" \
  FLUTTER_REMOTE_MAX_DIMENSION="$FR_MAX_DIMENSION" \
  FLUTTER_REMOTE_VIDEO_FPS="$FR_VIDEO_FPS" \
  FLUTTER_REMOTE_VIDEO_QUALITY="$FR_VIDEO_QUALITY" \
    nohup node "$HERE/gate.cjs" > gate.log 2>&1 &
  disown
  for i in $(seq 1 30); do
    if curl -fsS -o /dev/null "http://127.0.0.1:$GATE_PORT/__flutter-remote/healthz" 2>/dev/null; then break; fi
    sleep 0.5
  done
  echo "Auth gate proxy running on port $GATE_PORT"
  cat gate.log || true
}

open_tunnel() {
  # Download cloudflared only if not restored from cache
  if [ ! -f cloudflared ]; then
    echo "Downloading cloudflared tunnel client..."
    curl -fsSL -o cloudflared.tgz https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-darwin-arm64.tgz
    tar -xzf cloudflared.tgz
    rm -f cloudflared.tgz
  else
    echo "cloudflared restored from cache, skipping download"
  fi
  chmod +x cloudflared

  # QUIC (UDP-based) handles packet loss significantly better than HTTP/2 (TCP).
  # On a lossy connection, TCP stalls the entire stream waiting for retransmits.
  # QUIC drops individual datagrams and recovers per-stream — video keeps playing.
  # Falls back to http2 automatically if UDP is blocked by the network.
  TUNNEL_PROTO="$FR_TUNNEL_PROTOCOL"
  nohup ./cloudflared tunnel --no-autoupdate \
    --protocol "$TUNNEL_PROTO" \
    --url "http://127.0.0.1:$GATE_PORT" \
    --logfile cloudflared.log > /dev/null 2>&1 &
  disown

  TUNNEL_URL=""
  for i in $(seq 1 60); do
    TUNNEL_URL=$(grep -Eo 'https://[a-z0-9-]+\.trycloudflare\.com' cloudflared.log 2>/dev/null | head -1 || true)
    if [ -n "$TUNNEL_URL" ]; then break; fi
    sleep 2
  done

  [ -n "$TUNNEL_URL" ] || { echo "::error::Cloudflare tunnel failed to establish (protocol=$TUNNEL_PROTO)"; cat cloudflared.log; exit 1; }
  echo "Tunnel established (protocol=$TUNNEL_PROTO): $TUNNEL_URL"
  printf 'UDID=%s\nTUNNEL_URL=%s\n' "$UDID" "$TUNNEL_URL" > "$STATE_FILE"

  report pending "Building Flutter iOS application..." "$TUNNEL_URL"
}

build_app() {
  echo "Preparing Flutter dependencies..."
  flutter pub get

  # No --no-codesign: Xcode signs Simulator builds locally ("Sign to Run Locally", no team or
  # certificate needed) and embeds the Simulator entitlements. An unsigned build has no
  # application-identifier, so every Keychain call fails with -34018 (flutter_secure_storage,
  # firebase_auth, sign-in plugins...) and apps that keep their session there cannot log in.
  BUILD_ARGS=(
    ios
    --simulator
  )

  if [ "$FR_BUILD_MODE" = 'profile' ] || [ "$FR_BUILD_MODE" = 'release' ]; then
    echo "::warning::Flutter does not support '$FR_BUILD_MODE' mode on iOS Simulator (physical devices only). Using --debug mode."
    BUILD_ARGS+=(--debug)
  else
    BUILD_ARGS+=(--debug)
  fi

  if [ -n "$FR_FLAVOR" ]; then
    BUILD_ARGS+=(--flavor "$FR_FLAVOR")
  fi

  if [ -n "$FR_TARGET" ]; then
    BUILD_ARGS+=(-t "$FR_TARGET")
  fi

  if [ -n "$FR_DART_DEFINES" ]; then
    IFS=',' read -ra DEFINES <<< "$FR_DART_DEFINES"
    for def in "${DEFINES[@]}"; do
      if [ -n "$def" ]; then
        BUILD_ARGS+=(--dart-define "$def")
      fi
    done
  fi

  echo "Building iOS Simulator app: flutter build ${BUILD_ARGS[*]}"
  START_TIME=$(date +%s)
  if ! flutter build "${BUILD_ARGS[@]}"; then
    echo "::error::Flutter Simulator build failed. Check the workflow logs above for Xcode/Flutter errors."
    exit 1
  fi
  END_TIME=$(date +%s)
  echo "Flutter iOS Simulator build completed in $((END_TIME - START_TIME))s"

  APP_PATH=$(find build/ios/iphonesimulator -maxdepth 2 -name '*.app' -type d | head -1)
  [ -n "$APP_PATH" ] || { echo "::error::No .app found in build/ios/iphonesimulator"; exit 1; }
  echo "Discovered generated .app bundle: $APP_PATH"

  mkdir -p build/flutter-remote-app
  cp -R "$APP_PATH" build/flutter-remote-app/
}

install_and_launch() {
  APP_PATH=$(find build/flutter-remote-app -maxdepth 2 -name '*.app' -type d | head -1)
  [ -n "$APP_PATH" ] || { echo "::error::No .app found in build/flutter-remote-app"; exit 1; }

  echo "Installing $APP_PATH onto simulator $UDID..."
  xcrun simctl install "$UDID" "$APP_PATH"

  BUNDLE_ID=$(/usr/libexec/PlistBuddy -c "Print :CFBundleIdentifier" "$APP_PATH/Info.plist" 2>/dev/null || true)
  if [ -z "$BUNDLE_ID" ]; then
    BUNDLE_ID=$(defaults read "$APP_PATH/Info" CFBundleIdentifier 2>/dev/null || true)
  fi
  [ -n "$BUNDLE_ID" ] || { echo "::error::Could not determine CFBundleIdentifier from $APP_PATH/Info.plist"; exit 1; }
  echo "Detected Bundle Identifier: $BUNDLE_ID"

  echo "Launching Flutter application ($BUNDLE_ID)..."
  if ! xcrun simctl launch "$UDID" "$BUNDLE_ID"; then
    echo "::error::Flutter application was built successfully, but failed to launch inside the iOS Simulator."
    exit 1
  fi
  echo "Flutter application launched successfully inside iOS Simulator."
}

# A subshell: it changes directory, and the rest of `start` must stay in the project root.
install_prebuilt() (
  mkdir -p /tmp/flutter-remote-prebuilt
  cd /tmp/flutter-remote-prebuilt

  if [ -n "$FR_APP_RELEASE_ASSET" ]; then
    echo "Downloading prebuilt app from GitHub Release: $FR_APP_RELEASE_ASSET"
    gh release download flutter-remote-build -p "$FR_APP_RELEASE_ASSET"
    ARCHIVE="$FR_APP_RELEASE_ASSET"
  elif [ -n "$FR_APP_URL" ]; then
    echo "Downloading prebuilt app from URL: $FR_APP_URL"
    curl -fsSL "$FR_APP_URL" -o app-archive
    ARCHIVE="app-archive"
  else
    echo "::error::Neither app_url nor app_release_asset provided for mode=app"
    exit 1
  fi

  if file "$ARCHIVE" | grep -qiE 'gzip|tar'; then
    tar -xzf "$ARCHIVE" || tar -xf "$ARCHIVE"
  elif file "$ARCHIVE" | grep -qi 'zip'; then
    unzip -q "$ARCHIVE"
  fi

  PREBUILT_APP=$(find . -maxdepth 3 -name '*.app' -type d | head -1)
  [ -n "$PREBUILT_APP" ] || { echo "::error::No .app bundle discovered in downloaded archive"; exit 1; }

  # Validate that it is a simulator app
  PLATFORMS=$(/usr/libexec/PlistBuddy -c "Print :CFBundleSupportedPlatforms" "$PREBUILT_APP/Info.plist" 2>/dev/null || true)
  if [ -n "$PLATFORMS" ] && ! echo "$PLATFORMS" | grep -qi 'iPhoneSimulator'; then
    echo "::error::This is a device iOS build. flutter-remote requires an iOS Simulator build."
    exit 1
  fi

  xcrun simctl install "$UDID" "$PREBUILT_APP"
  BUNDLE_ID=$(/usr/libexec/PlistBuddy -c "Print :CFBundleIdentifier" "$PREBUILT_APP/Info.plist" 2>/dev/null || defaults read "$PREBUILT_APP/Info" CFBundleIdentifier)
  xcrun simctl launch "$UDID" "$BUNDLE_ID"
  echo "Prebuilt app launched."
)

install_agent_device() {
  echo "Installing agent-device v$FR_AGENT_DEVICE_VERSION..."
  npm install -g "agent-device@$FR_AGENT_DEVICE_VERSION"
}

start_agent_device() {
  agent-device proxy --port "$AGENT_PORT" --device "$UDID" &
  for i in {1..30}; do
    if nc -z 127.0.0.1 "$AGENT_PORT" 2>/dev/null; then break; fi
    sleep 0.2
  done
  echo "agent-device proxy running on port $AGENT_PORT"
}

phase_start() {
  : "${FR_SESSION:?FR_SESSION is required}"
  : "${FR_GATE_TOKEN:?FR_GATE_TOKEN is required}"

  boot_simulator
  start_serve_sim
  install_peer_deps
  start_peer
  start_gate
  open_tunnel

  if [ "$FR_MODE" = "build" ]; then
    # A restored cache already holds the .app: skip the build (the cache is saved by the wrapper).
    if [ -z "$(find build/flutter-remote-app -maxdepth 2 -name '*.app' -type d 2>/dev/null | head -1)" ]; then
      build_app
    fi
    install_and_launch
  elif [ "$FR_MODE" = "app" ]; then
    install_prebuilt
  fi

  report success "Flutter Simulator is live" "$TUNNEL_URL"

  if [ "$FR_AGENT_DEVICE" = "true" ]; then
    install_agent_device
    start_agent_device
  fi
}

phase_hold() {
  if [ -f "$STATE_FILE" ]; then . "$STATE_FILE"; fi
  echo "Stream is active. Holding session open for $FR_MINUTES minutes..."
  tail -f webrtc-peer.log gate.log &
  TAIL_PID=$!
  sleep $((FR_MINUTES * 60))
  kill $TAIL_PID 2>/dev/null || true
}

phase_end() {
  if [ -f "$STATE_FILE" ]; then . "$STATE_FILE" || true; fi
  report failure "Simulator session ended" || true
}

case "${1:-}" in
  fingerprint) phase_fingerprint ;;
  start) phase_start ;;
  hold) phase_hold ;;
  end) phase_end ;;
  *) echo "usage: session.sh fingerprint|start|hold|end" >&2; exit 2 ;;
esac
